1	import { describe, it, expect, vi } from 'vitest';
2	import { render } from 'vitest-browser-svelte';
3	import ReceiptImageViewer from './ReceiptImageViewer.svelte';
4	
5	/**
6	 * Behaviour tests for the real <ReceiptImageViewer> zoom controls (#{#zom1a}).
7	 *
8	 * The previous spec was hollow: every `it()` re-declared the zoom arithmetic
9	 * inline (`let zoom = 100; zoom += 50; expect(zoom).toBe(150)`) and asserted
10	 * against its own copy — 859 lines that passed no matter what the component did
11	 * (its header even admitted it was stale TDD RED-phase scaffolding). These render
12	 * the actual component and drive its buttons/keyboard, asserting the visible
13	 * zoom %, the disabled boundaries, and close wiring.
14	 *
15	 * Pointer gestures (wheel-zoom, drag-pan, pinch) stay a manual-verify item — they
16	 * use imperative `{ passive: false }` listeners that unit tests can't faithfully
17	 * drive (tracked in the backlog). The button + keyboard path is the deterministic,
18	 * render-testable surface, and it's where the real clamp/snap logic lives.
19	 */
20	const props = { imageUrl: 'http://localhost/receipt.jpg', show: true };
21	
22	describe('ReceiptImageViewer', () => {
23		it('renders nothing until show is true', async () => {
24			const screen = render(ReceiptImageViewer, { imageUrl: 'http://localhost/r.jpg', show: false });
25			await expect.element(screen.getByRole('dialog')).not.toBeInTheDocument();
26		});
27	
28		it('opens at 100% with zoom-out disabled and zoom-in enabled', async () => {
29			const screen = render(ReceiptImageViewer, { ...props });
30	
31			await expect.element(screen.getByRole('dialog')).toBeVisible();
32			await expect.element(screen.getByText('100%', { exact: true })).toBeVisible();
33			await expect.element(screen.getByRole('button', { name: 'Zoom out' })).toBeDisabled();
34			await expect.element(screen.getByRole('button', { name: 'Zoom in' })).toBeEnabled();
35		});
36	
37		it('steps up by 50% on each Zoom in click and clamps/disables at 400%', async () => {
38			const screen = render(ReceiptImageViewer, { ...props });
39			const zoomIn = screen.getByRole('button', { name: 'Zoom in' });
40	
41			await zoomIn.click();
42			await expect.element(screen.getByText('150%', { exact: true })).toBeVisible();
43	
44			await zoomIn.click(); // 200
45			await zoomIn.click(); // 250
46			await zoomIn.click(); // 300
47			await zoomIn.click(); // 350
48			await zoomIn.click(); // 400
49			await expect.element(screen.getByText('400%', { exact: true })).toBeVisible();
50			await expect.element(zoomIn).toBeDisabled();
51		});
52	
53		it('steps back down on Zoom out', async () => {
54			const screen = render(ReceiptImageViewer, { ...props });
55	
56			await screen.getByRole('button', { name: 'Zoom in' }).click(); // 150
57			await screen.getByRole('button', { name: 'Zoom in' }).click(); // 200
58			await screen.getByRole('button', { name: 'Zoom out' }).click(); // 150
59			await expect.element(screen.getByText('150%', { exact: true })).toBeVisible();
60		});
61	
62		it('Reset returns to 100%', async () => {
63			const screen = render(ReceiptImageViewer, { ...props });
64	
65			await screen.getByRole('button', { name: 'Zoom in' }).click(); // 150
66			await screen.getByRole('button', { name: 'Zoom in' }).click(); // 200
67			await screen.getByRole('button', { name: 'Reset zoom to 100%' }).click();
68			await expect.element(screen.getByText('100%', { exact: true })).toBeVisible();
69		});
70	
71		it('supports keyboard zoom shortcuts (+ / - / 0)', async () => {
72			const screen = render(ReceiptImageViewer, { ...props });
73	
74			window.dispatchEvent(new KeyboardEvent('keydown', { key: '+', bubbles: true }));
75			await expect.element(screen.getByText('150%', { exact: true })).toBeVisible();
76	
77			window.dispatchEvent(new KeyboardEvent('keydown', { key: '-', bubbles: true }));
78			await expect.element(screen.getByText('100%', { exact: true })).toBeVisible();
79	
80			window.dispatchEvent(new KeyboardEvent('keydown', { key: '+', bubbles: true }));
81			window.dispatchEvent(new KeyboardEvent('keydown', { key: '0', bubbles: true }));
82			await expect.element(screen.getByText('100%', { exact: true })).toBeVisible();
83		});
84	
85		it('calls onclose from the close button and from Escape', async () => {
86			const onclose = vi.fn();
87			const screen = render(ReceiptImageViewer, { ...props, onclose });
88	
89			await screen.getByRole('button', { name: 'Close image viewer' }).click();
90			expect(onclose).toHaveBeenCalledTimes(1);
91	
92			window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
93			expect(onclose).toHaveBeenCalledTimes(2);
94		});
95	
96		it('renders a PDF in an iframe with no zoom controls', async () => {
97			const screen = render(ReceiptImageViewer, {
98				imageUrl: 'http://localhost/receipt.pdf',
99				show: true,
100				isPdf: true,
101				altText: 'Receipt PDF'
102			});
103	
104			await expect.element(screen.getByTitle('Receipt PDF')).toBeVisible();
105			await expect.element(screen.getByRole('button', { name: 'Zoom in' })).not.toBeInTheDocument();
106		});
107	});
