99		it('renders a foreign-currency expense without an estimate when the rate is null', async () => {
100			setSession(fakeSession());
101			setExpenses([makeExpense({ total_amount: 45, currency: 'EUR', exchange_rate_to_cad: null })]);
102	
103			const screen = render(ExpensesPage);
104	
105			await expect.element(screen.getByText('€45.00')).toBeVisible();
106			await expect.element(screen.getByText(/≈\$/)).not.toBeInTheDocument();
107		});
108	
109		it('shows the expense count summary', async () => {
110			setSession(fakeSession());
111			setExpenses([makeExpense(), makeExpense({ receipt_id: 'receipt-2' })]);
112	
113			const screen = render(ExpensesPage);
114	
115			await expect.element(screen.getByText(/Showing 2 of 2 expenses/)).toBeVisible();
