121			setExpenses([
122				makeExpense({
123					receipt_id: 'a',
124					merchant_name: 'Alpha Store',
125					category_id: 'cat-1',
126					category_name: 'Food'
127				}),
128				makeExpense({ receipt_id: 'b', merchant_name: 'Beta Store', category_id: null })
129			]);
130	
131			const screen = render(ExpensesPage);
132	
133			await expect.element(screen.getByText('Alpha Store')).toBeVisible();
134			await expect.element(screen.getByText('Beta Store')).toBeVisible();
135	
136			// The filter toggle is the first "Uncategorized" button (FilterPanel renders above
137			// the table, so it precedes the row's own category-cell trigger / dropdown option).
138			await screen
139				.getByRole('button', { name: /Uncategorized/ })
140				.first()
141				.click();
142	
143			await expect.element(screen.getByText('Beta Store')).toBeVisible();
144			await expect.element(screen.getByText('Alpha Store')).not.toBeInTheDocument();
145			// #{#flt1a} the count summary reflects the active filter.
146			await expect.element(screen.getByText(/Showing 1 of 2 expenses/)).toBeVisible();
147		});
148	
149		it('filters to a chosen category via the Category dropdown (#{#exp7a})', async () => {
150			setSession(fakeSession());
151			setCategories([
152				{ id: 'cat-food', name: 'Food', color: '#10B981' } as Category,
153				{ id: 'cat-travel', name: 'Travel', color: '#3B82F6' } as Category
154			]);
155			setExpenses([
156				makeExpense({
157					receipt_id: 'a',
158					merchant_name: 'Grocer',
159					category_id: 'cat-food',
160					category_name: 'Food'
161				}),
162				makeExpense({
163					receipt_id: 'b',
164					merchant_name: 'Airline',
165					category_id: 'cat-travel',
166					category_name: 'Travel'
167				})
