175			// Open the Category filter dropdown (top of page), then pick Travel. The row's own
176			// category cell also renders a 'Travel' button, so target the first (the filter).
177			await screen.getByRole('button', { name: /^Category/ }).click();
178			await screen.getByRole('button', { name: 'Travel' }).first().click();
179	
180			await expect.element(screen.getByText('Airline')).toBeVisible();
181			await expect.element(screen.getByText('Grocer')).not.toBeInTheDocument();
182		});
183	});
