1	import { describe, it, expect } from 'vitest';
2	import { readFileSync } from 'fs';
3	import { join } from 'path';
4	
5	/**
6	 * Auth Route Guard — residual page-level guard.
7	 *
8	 * The layout-level guard (#{#ath1a} gate + #{#ath1b} not-logged-in message) is now
9	 * a behavior test in layout-render.svelte.spec.ts, which renders +layout.svelte and
10	 * asserts what a user sees per auth/route combination.
11	 *
12	 * What remains here is #{#ath1c}: the protected pages must NOT re-introduce their own
13	 * `window.location.href = '/login'` redirect — the layout owns the redirect, and a
14	 * per-page one would double-fire / conflict. This stays a source check because it
15	 * asserts the ABSENCE of an anti-pattern across four page files; converting it to
16	 * behavior means rendering each page unauthenticated, which the per-page render slices
17	 * (docs/product-backlog.md → Test-suite cleanup) will do once those pages have harnesses.
18	 */
19	describe('Auth Route Guard — #{#ath1c} no per-page redirect', () => {
20		const protectedPages = [
21			{ name: 'receipts', path: join(process.cwd(), 'src/routes/receipts/+page.svelte') },
22			{ name: 'transactions', path: join(process.cwd(), 'src/routes/transactions/+page.svelte') },
23			{ name: 'expenses', path: join(process.cwd(), 'src/routes/expenses/+page.svelte') },
24			{ name: 'reconciliation', path: join(process.cwd(), 'src/routes/reconciliation/+page.svelte') }
25		];
26	
27		for (const page of protectedPages) {
28			it(`does not self-redirect to /login in the ${page.name} page`, () => {
29				const content = readFileSync(page.path, 'utf-8');
30	
31				const hasAuthRedirect =
32					content.includes("window.location.href = '/login'") ||
33					content.includes('window.location.href = "/login"');
34	
35				expect(hasAuthRedirect).toBe(false);
36			});
37		}
38	});
