1	import { describe, it, expect, vi, beforeEach } from 'vitest';
2	import { render } from 'vitest-browser-svelte';
3	import {
4		pageStore,
5		supabaseMock,
6		setRoute,
7		setSession,
8		setSessionPending,
9		fakeSession,
10		resetHarness
11	} from './harness/appMocks';
12	
13	// Replace the SvelteKit page store and the Supabase singleton before the layout
14	// (imported transitively via LayoutHarness) mounts. See harness/appMocks.ts.
15	vi.mock('$app/stores', () => ({ page: pageStore }));
16	vi.mock('$lib/supabaseClient', () => ({ supabase: supabaseMock }));
17	
18	import LayoutHarness from './harness/LayoutHarness.svelte';
19	
20	/**
21	 * Behavior tests for +layout.svelte — the app-wide auth gate and header nav.
22	 *
23	 * Replaces two source-introspection specs that regex'd the layout source:
24	 *   - auth-route-guard.spec.ts  (#{#ath1a/b/c})
25	 *   - layout-navigation.spec.ts (#{#upp1b}, #{#upp3a})
26	 * These render the real layout and assert what a user actually sees for each
27	 * auth/route combination. Built on the route-render harness (harness/appMocks.ts).
28	 */
29	describe('+layout.svelte', () => {
30		beforeEach(resetHarness);
31	
32		describe('auth gate (#{#ath1a}, #{#ath1b})', () => {
33			it('renders the protected page content when signed in', async () => {
34				setSession(fakeSession());
35				setRoute('/expenses');
36	
37				const screen = render(LayoutHarness);
38	
39				await expect.element(screen.getByTestId('page-content')).toBeVisible();
40			});
41	
42			it('shows the not-logged-in message instead of the page on a protected route when signed out', async () => {
43				setSession(null);
44				setRoute('/expenses');
45	
46				const screen = render(LayoutHarness);
47	
48				await expect.element(screen.getByText('You are not logged in.')).toBeVisible();
49				await expect.element(screen.getByRole('link', { name: 'Go to login' })).toBeVisible();
50				await expect.element(screen.getByTestId('page-content')).not.toBeInTheDocument();
51			});
52	
53			it('renders page content on a public route even when signed out', async () => {
54				// '/login' is in the layout's publicRoutes allow-list.
55				setSession(null);
56				setRoute('/login');
57	
58				const screen = render(LayoutHarness);
59	
60				await expect.element(screen.getByTestId('page-content')).toBeVisible();
61				await expect.element(screen.getByText('You are not logged in.')).not.toBeInTheDocument();
62			});
63	
64			it('shows the Loading placeholder before the session check resolves', async () => {
65				// Protected route, getSession still pending → neither the page nor the
66				// not-logged-in message yet.
67				setSessionPending();
68				setRoute('/expenses');
69	
70				const screen = render(LayoutHarness);
71	
72				await expect.element(screen.getByText('Loading…')).toBeVisible();
73				await expect.element(screen.getByTestId('page-content')).not.toBeInTheDocument();
74				await expect.element(screen.getByText('You are not logged in.')).not.toBeInTheDocument();
75			});
76		});
77	
78		describe('navigation (#{#ath1a})', () => {
79			it('shows the full authenticated nav (incl. Logout) when signed in', async () => {
80				setSession(fakeSession());
81				setRoute('/expenses');
82	
83				const screen = render(LayoutHarness);
84	
85				await expect
86					.element(screen.getByRole('link', { name: 'Receipts', exact: true }))
87					.toBeVisible();
88				await expect.element(screen.getByRole('link', { name: 'Transactions' })).toBeVisible();
89				await expect.element(screen.getByRole('link', { name: 'Reconciliation' })).toBeVisible();
90				await expect.element(screen.getByRole('button', { name: 'Logout' })).toBeVisible();
91			});
92	
93			it('shows only the Login link and no protected nav when signed out', async () => {
94				setSession(null);
95				setRoute('/login');
96	
97				const screen = render(LayoutHarness);
98	
99				await expect.element(screen.getByRole('link', { name: 'Login' })).toBeVisible();
100				await expect
101					.element(screen.getByRole('link', { name: 'Receipts', exact: true }))
102					.not.toBeInTheDocument();
103				await expect.element(screen.getByRole('button', { name: 'Logout' })).not.toBeInTheDocument();
104			});
105	
106			it('preserves dateFrom/dateTo filters in nav link hrefs', async () => {
107				setSession(fakeSession());
108				setRoute('/expenses', '?dateFrom=2026-01-01&dateTo=2026-01-31');
109	
110				const screen = render(LayoutHarness);
111	
112				const receipts = screen.getByRole('link', { name: 'Receipts', exact: true });
113				await expect
114					.element(receipts)
115					.toHaveAttribute('href', '/receipts?dateFrom=2026-01-01&dateTo=2026-01-31');
116			});
117		});
118	
119		describe('Profile link (#{#upp1b}, #{#upp3a})', () => {
120			it('exposes the Profile link with its accessible label when signed in', async () => {
121				setSession(fakeSession());
122				setRoute('/expenses');
123	
124				const screen = render(LayoutHarness);
125	
126				await expect.element(screen.getByRole('link', { name: 'View profile' })).toBeVisible();
127			});
128	
129			it('marks the Profile link as the current page when on /profile', async () => {
130				setSession(fakeSession());
131				setRoute('/profile');
132	
133				const screen = render(LayoutHarness);
134	
135				const profile = screen.getByRole('link', { name: 'View profile' });
136				await expect.element(profile).toHaveAttribute('aria-current', 'page');
137			});
138	
139			it('does not mark the Profile link current when on another route', async () => {
140				setSession(fakeSession());
141				setRoute('/expenses');
142	
143				const screen = render(LayoutHarness);
144	
145				const profile = screen.getByRole('link', { name: 'View profile' });
146				await expect.element(profile).not.toHaveAttribute('aria-current');
147			});
148	
149			it('hides the Profile link when signed out', async () => {
150				// NOTE: the deleted layout-navigation.spec.ts asserted the Profile link is
151				// "visible to all users" via a 200-char source-proximity heuristic — a false
152				// positive. The link actually lives inside {#if $session}, so it is hidden
153				// when signed out. This asserts the real behavior.
154				setSession(null);
155				setRoute('/login');
156	
157				const screen = render(LayoutHarness);
158	
159				await expect.element(screen.getByRole('link', { name: 'Login' })).toBeVisible();
160				await expect
161					.element(screen.getByRole('link', { name: 'View profile' }))
162					.not.toBeInTheDocument();
163			});
164		});
165	});
