1	/**
2	 * Test Suite for Receipt Date Parsing Correction
3	 *
4	 * Specs:
5	 *   #{#rdc1a} - Plausibility window (<=90 days before upload, not future)
6	 *   #{#rdc3a} - Deterministic format-permutation parser (pure, local-time)
7	 *   #{#rdc3b} - Candidate format list + closest-to-upload tie-breaking
8	 *   #{#rdc4a} - Correction algorithm (accept-if-plausible, else permute-and-score)
9	 *
10	 * Authority: platform (rdc1a, rdc3a, rdc4a), developer (rdc3b)
11	 *
12	 * All functions are pure: the reference "now" is the passed uploadDate, never
13	 * Date.now(). No fake timers required.
14	 */
15	
16	import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
17	import {
18		PLAUSIBILITY_WINDOW_DAYS,
19		isPlausible,
20		parseRawDate,
21		correctDate,
22		resolveOcrReceiptDate
23	} from './receiptDateCorrection';
24	import { CORRECTION_CORPUS } from './receiptDateCorrection.fixtures';
25	import { toDate } from './dateConversion';
26	
27	// Local-midnight constructor (year, monthIndex, day) — avoids UTC shift.
28	const d = (y: number, m: number, day: number) => new Date(y, m - 1, day);
29	
30	describe('#{#rdc1a} - Plausibility window', () => {
31		const upload = d(2025, 6, 7); // 2025-06-07 local
