71		const mockReceiptsSelect = vi.fn().mockReturnValue({ eq: mockReceiptsEq });
72	
73		const mockTransactionsLte = vi.fn().mockResolvedValue({
74			data: transactions,
75			error: null
76		});
77		const mockTransactionsGte = vi.fn().mockReturnValue({ lte: mockTransactionsLte });
78		const mockTransactionsEq = vi.fn().mockReturnValue({ gte: mockTransactionsGte });
79		const mockTransactionsSelect = vi.fn().mockReturnValue({ eq: mockTransactionsEq });
