81		vi.mocked(supabase.from).mockImplementation((table: string) => {
82			const builder =
83				table === 'receipts' ? { select: mockReceiptsSelect } : { select: mockTransactionsSelect };
84			return builder as unknown as ReturnType<typeof supabase.from>;
85		});
86	}
